# area: self_classmethods
# hypothesis: Self in an inherited classmethod and property binds to the class the call is made on, even through a diamond MRO.
# spec: PEP 673 - Self in a classmethod binds to the class it is called on.
from typing import Self, reveal_type


class Root:
    @classmethod
    def make(cls) -> Self:
        return cls()

    def same(self, other: Self) -> Self:
        return self


class Left(Root):
    pass


class Right(Root):
    pass


class Bottom(Left, Right):
    @property
    def tag(self) -> Self:
        return self


reveal_type(Root.make())
reveal_type(Bottom.make())
reveal_type(Bottom().tag)
reveal_type(Left().same(Left()))

b = Bottom.make()
t = Bottom().tag
print(type(b).__name__, type(t).__name__, type(Root.make()).__name__)
print(type(Left().same(Left())).__name__)
print(type(Bottom().same(Bottom())).__name__)

try:
    Left().same(Right())  # expect-error: Right is not a Left
except TypeError:
    print('rejected at runtime')
